module count_ones (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] l,\n    input [7:0] r,\n    output reg [15:0] count,\n    output reg done\n);\n\n    // State encoding\n    localparam [2:0] IDLE   = 3'd0;\n    localparam [2:0] CHECK  = 3'd1;\n    localparam [2:0] COMPUTE = 3'd2;\n    localparam [2:0] DONE   = 3'd3;\n\n    reg [2:0] state;\n    reg [7:0] n_reg, l_reg, r_reg, current_i;\n    reg [3:0] msb_index;\n\n    function [3:0] ctz_func;\n        input [7:0] val;\n        begin\n            ctz_func = 4'd0;\n            if (val[0]) ctz_func = 4'd0;\n            else if (val[1]) ctz_func = 4'd1;\n            else if (val[2]) ctz_func = 4'd2;\n            else if (val[3]) ctz_func = 4'd3;\n            else if (val[4]) ctz_func = 4'd4;\n            else if (val[5]) ctz_func = 4'd5;\n            else if (val[6]) ctz_func = 4'd6;\n            else if (val[7]) ctz_func = 4'd7;\n        end\n    endfunction\n\n    wire [3:0] ctz = ctz_func(current_i);\n    wire [3:0] pos = msb_index - ctz;\n    wire bit_val = n_reg[pos];\n\n    // Find MSB index\n    always @(*) begin\n        msb_index = 4'd0;\n        if (n_reg[7]) msb_index = 4'd7;\n        else if (n_reg[6]) msb_index = 4'd6;\n        else if (n_reg[5]) msb_index = 4'd5;\n        else if (n_reg[4]) msb_index = 4'd4;\n        else if (n_reg[3]) msb_index = 4'd3;\n        else if (n_reg[2]) msb_index = 4'd2;\n        else if (n_reg[1]) msb_index = 4'd1;\n        else if (n_reg[0]) msb_index = 4'd0;\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            count <= 16'd0;\n            n_reg <= 8'd0;\n            l_reg <= 8'd0;\n            r_reg <= 8'd0;\n            current_i <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        l_reg <= l;\n                        r_reg <= r;\n                        current_i <= l;\n\n                        if (n == 8'd0) begin\n                            count <= 16'd0;\n                            state <= DONE;\n                        end else begin\n                            count <= 16'd0;\n                            state <= CHECK;\n                        end\n                    end\n                end\n\n                CHECK: begin\n                    if (current_i <= r_reg) begin\n                        state <= COMPUTE;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n\n                COMPUTE: begin\n                    count <= count + {15'd0, bit_val};\n                    current_i <= current_i + 8'd1;\n                    state <= CHECK;\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule